def detect_cycle_added_edge(predecessor, successor):
    queue = [successor]
    visited = set()
    path_nodes = []
    while queue:
        cur = queue.pop(0)
        if cur in visited:
            continue
        visited.add(cur)
        path_nodes.append(cur)
        if cur == predecessor:
            return True, list(path_nodes)
        rows = frappe.get_all("Task Relation", filters={"predecessor": cur, "is_active": 1}, fields=["parent"])
        for r in rows:
            nxt = r["parent"]
            if nxt not in visited:
                queue.append(nxt)
    return False, []

def validate_relation(parent_successor, predecessor, rel_type, buffer_days):
    if parent_successor == predecessor:
        return {"ok": False, "error": _("Predecessor can't be same as successor")}
    try:
        parent_doc = frappe.get_doc("Task", parent_successor)
        pred_doc = frappe.get_doc("Task", predecessor)
    except Exception as e:
        return {"ok": False, "error": f"Task not found: {e}"}
    proj_parent = parent_doc.get("project", None)
    proj_pred = pred_doc.get("project", None)
    if proj_parent != proj_pred:
        return {"ok": False, "error": _("Tasks must belong to the same project")}
    existing = frappe.get_all("Task Relation", filters={"predecessor": predecessor, "parent": parent_successor, "type": rel_type})
    if existing:
        return {"ok": False, "error": _("Duplicate relation exists")}
    cycle_path = detect_cycle_added_edge(predecessor, parent_successor)
    if cycle_path[0]:
        return {"ok": False, "error": _("Cycle detected"), "path": cycle_path[1]}
    return {"ok": True}
    
