def add_business_days(start_date, offset_days, holiday_dates):
    if start_date is None:
        return None
    cur = parse_date(start_date)
    if not cur:
        return None
    step = 1 if int(offset_days) >= 0 else -1
    remaining = abs(int(offset_days))
    while remaining > 0:
        next_str = frappe.utils.add_days(cur, step)
        cur = frappe.utils.getdate(next_str)
        if cur.weekday() in (5, 6):
            continue
        if format_date(cur) in holiday_dates:
            continue
        remaining = remaining - 1
    return cur

# ------------------ добавлен helper для подсчёта рабочих дней (включительно) ------------------
def business_days_inclusive(start_date, end_date, holiday_dates):
    """
    Возвращает количество рабочих дней между start_date и end_date включительно,
    учитывая weekend (sat/sun) и holiday_dates (set of 'YYYY-MM-DD').
    Если start_date > end_date возвращает 0.
    """
    if not start_date or not end_date:
        return None
    # если переданы строки — конвертируем (parse_date уже возвращает date)
    s = start_date 
    e = end_date 
    if not s or not e:
        return None
    # если границы в "обратном" порядке — возвращаем 0 (нет длительности)
    if s > e:
        return 0
    count = 0
    cur = s
    while cur <= e:
        if format_date(cur) not in holiday_dates:
            count = count + 1
        # шаг на 1 календарный день
        next_str = frappe.utils.add_days(cur, 1)
        cur = frappe.utils.getdate(next_str)
    if not count:
        count = frappe.utils.date_diff( e, s ) + 1
    return count

def bfs_collect_subgraph(start_nodes, direction="downstream", max_nodes=5000):
    queue = []
    if isinstance(start_nodes, (list, tuple, set)):
        for s in start_nodes:
            queue.append(s)
    else:
        queue.append(start_nodes)
    visited = set()
    edges_set = set()
    nodes_set = set()
    relations = []
    while queue and len(nodes_set) <= max_nodes:
        cur = queue.pop(0)
        if cur in visited:
            continue
        visited.add(cur)
        nodes_set.add(cur)
        if direction in ("downstream", "both"):
            rows = frappe.get_all("Task Relation", filters={"predecessor": cur, "is_active": 1}, fields=["parent","predecessor","type","buffer_days"])
            relations.extend(rows)
            for r in rows:
                frm = r["predecessor"]
                to = r["parent"]
                edges_set.add((frm, to))
                if to not in visited:
                    queue.append(to)
        if direction in ("upstream", "both") or cur in start_nodes:
            rows = frappe.get_all("Task Relation", filters={"parent": cur, "is_active": 1}, fields=["parent","predecessor","type","buffer_days"])
            relations.extend(rows)
            for r in rows:
                frm = r["predecessor"]
                to = r["parent"]
                edges_set.add((frm, to))
                if frm not in visited:
                    queue.append(frm)
    return nodes_set, list(edges_set), relations

def topological_sort(nodes_iterable, edges_list):
    nodes = list(nodes_iterable)
    in_deg = {}
    adj = {}
    for n in nodes:
        in_deg[n] = 0
        adj[n] = []
    for u, v in edges_list:
        if u not in in_deg:
            in_deg[u] = 0
            adj[u] = []
        if v not in in_deg:
            in_deg[v] = 0
            adj[v] = []
        in_deg[v] = in_deg.get(v, 0) + 1
        adj[u].append(v)
    queue = []
    for n, deg in list(in_deg.items()):
        if deg == 0:
            queue.append(n)
    order = []
    while queue:
        n = queue.pop(0)
        order.append(n)
        for m in adj.get(n, []):
            in_deg[m] = in_deg.get(m, 0) - 1
            if in_deg[m] == 0:
                queue.append(m)
    return order

def preview_propagation(changed_task, direction="downstream"):
    result = bfs_collect_subgraph(changed_task, direction=direction, max_nodes=5000)
    log( "bfs_collect_subgraph: " +  frappe.utils.cstr( result ) )
    nodes = result[0]
    edges = result[1]
    rows = result[2]
    node_count = len(nodes)
    heavy = node_count > SYNC_APPLY_THRESHOLD
    # load task docs
    task_docs = {}
    for n in nodes:
        task_docs[n] = frappe.get_doc("Task", n)
    log( "task_docs: " +  frappe.utils.cstr( task_docs ) )
    sim_values = {}
    if changed_task in task_docs and task_docs[changed_task]:
        doc = task_docs[changed_task]
        sim_start = doc.get("exp_start_date", None)
        sim_end = doc.get("exp_end_date", None)
        sim_values[changed_task] = {"sim_start": sim_start, "sim_end": sim_end}
    # holiday per project
    project_holidays = {}
    for n, doc in task_docs.items():
        proj = doc.get("project", None) if doc else None
        if proj and proj not in project_holidays:
            project_holidays[proj] = get_holiday_dates_for_project(proj)
    # helper to get start/end
    def get_start_end_of(n):
        doc = task_docs.get(n)
        if not doc:
            return None, None
        sv = sim_values.get(n, {})
        if sv:
            start = parse_date(sv.get("sim_start")) if sv.get("sim_start") is not None else parse_date(doc.get("exp_start_date", None))
            end = parse_date(sv.get("sim_end")) if sv.get("sim_end") is not None else parse_date(doc.get("exp_end_date", None))
        else:
            start = parse_date(doc.get("exp_start_date", None))
            end = parse_date(doc.get("exp_end_date", None))
        return start, end
    # Build incoming constraints map
    incoming = {}
    edge_meta = []
    seen_rows = set()
    for r in rows:
        #if not r.get("is_active"):
        #    continue
        key = (r["predecessor"], r["parent"], r["type"])
        if key in seen_rows:
            continue
        seen_rows.add(key)
        pred = r["predecessor"]
        succ = r["parent"]
        t = r["type"]
        buf = int(r.get("buffer_days") or 0)
        if succ not in incoming:
            incoming[succ] = []
        incoming[succ].append({"predecessor": pred, "type": t, "buffer": buf})
        edge_meta.append((pred, succ, t, buf))
    log( "incoming: " +  frappe.utils.cstr( incoming ) )
    log( "edge_meta: " +  frappe.utils.cstr( edge_meta ) )
    # Topological order
    edge_pairs = []
    for e in edge_meta:
        # e — кортеж вида (pred, succ, type, buffer) или подобный
        if len(e) >= 2:
            edge_pairs.append((e[0], e[1]))
    topo = topological_sort(nodes, edge_pairs)
    log( "topo: " +  frappe.utils.cstr( topo ) )
    if not topo:
        topo = list(nodes)
    # initialize proposed map
    proposed = {}
    for n in topo:
        cur = get_start_end_of(n)
        cur_s = cur[0] 
        cur_e = cur[1]
        proposed[n] = {"current_start": cur_s, "current_end": cur_e, "proposed_start": cur_s, "proposed_end": cur_e, "reasons": []}
    # propagate
    for n in topo:
        preds = incoming.get(n, [])
        if not preds:
            continue
        cand_start = proposed[n]["proposed_start"]
        cand_end = proposed[n]["proposed_end"]
        cur_start = proposed[n]["current_start"]
        cur_end = proposed[n]["current_end"]
        has_fs_ss = False
        for pr in preds:
            pred_name = pr["predecessor"]
            typ = pr["type"]
            buf = pr["buffer"]
            pred_prop = proposed.get(pred_name, {})
            pred_task = task_docs.get(pred_name)
            p_start = pred_prop.get("proposed_start") or parse_date( pred_task["exp_start_date"] )
            p_end = pred_prop.get("proposed_end") or parse_date( pred_task["exp_end_date"] )
            if not p_start and not p_end:
                proposed[n]["reasons"].append("predecessor % has no dates" % (pred_name))
                continue
            proj = task_docs.get(n).get("project", None) if task_docs.get(n) else None
            holidays = project_holidays.get(proj, set())
            kind = relation_kind(typ)
            if kind == "FS":
                has_fs_ss = True
                if p_end:
                    req_start = add_business_days(p_end, buf, holidays)
                    if cand_start is None or req_start > cand_start:
                        cand_start = req_start
                        proposed[n]["reasons"].append(_("FS from %s +%d => start >= %s") % (pred_name, buf, format_date(req_start)))
            elif kind == "SS":
                has_fs_ss = True
                if p_start:
                    req_start = add_business_days(p_start, buf, holidays)
                    if cand_start is None or req_start > cand_start:
                        cand_start = req_start
                        proposed[n]["reasons"].append(_("SS from %s +%d => start > =%s") % (pred_name, buf, format_date(req_start)))
            elif kind == "FF":
                if p_end:
                    req_end = add_business_days(p_end, buf, holidays)
                    if cand_end is None or req_end > cand_end:
                        cand_end = req_end
                        proposed[n]["reasons"].append(_("FF from %s +%d => end >= %s") % (pred_name, buf, format_date(req_end)))
            elif kind == "SF":
                if p_start:
                    req_end = add_business_days(p_start, buf, holidays)
                    if cand_end is None or req_end > cand_end:
                        cand_end = req_end
                        proposed[n]["reasons"].append(_("SF from %s +%d => end >= %s") % (pred_name, buf, format_date(req_end)))
        # ------------------ если есть FS/SS и старт сдвинут — сохранить длительность (в рабочих днях) ------------------
        # Логика: вычислить количество рабочих дней между cur_start и cur_end (включительно),
        # затем вычислить новый end как add_business_days(cand_start, business_days_count - 1).
        if has_fs_ss and cand_start is not None and cur_start is not None and cand_start != cur_start:
            # посчитать рабочие дни включительно на исходном интервале
            bdays = business_days_inclusive(cur_start, cur_end, holidays)
            if bdays is not None and bdays > 0:
                # new_end = cand_start + (bdays - 1) business days
                new_end_by_duration = add_business_days(cand_start, bdays - 1, holidays)
                # применяем, если это расширяет или если cand_end пустой
                if cand_end is None or (new_end_by_duration is not None and new_end_by_duration > cand_end):
                    cand_end = new_end_by_duration
                    proposed[n]["reasons"].append("Preserve duration: %d business days -> new end %s" % (bdays, format_date(new_end_by_duration)))

        proposed[n]["proposed_start"] = cand_start
        proposed[n]["proposed_end"] = cand_end
    log( "proposed: " +  frappe.utils.cstr( proposed ) )
    # build preview
    preview = []
    for n, vals in proposed.items():
        cur_s = vals["current_start"]
        cur_e = vals["current_end"]
        prop_s = vals["proposed_start"]
        prop_e = vals["proposed_end"]
        diff = False
        reasons = vals["reasons"][:]
        if prop_s and (not cur_s or prop_s != cur_s):
            diff = True
        if prop_e and (not cur_e or prop_e != cur_e):
            diff = True
        if diff:
            preview.append({
                "task": n,
                "subject": task_docs.get(n).get("subject", None),
                "current_start": format_date(cur_s),
                "current_end": format_date(cur_e),
                "proposed_start": format_date(prop_s),
                "proposed_end": format_date(prop_e),
                "reasons": reasons
            })
    return {"preview": preview, "node_count": node_count, "heavy": heavy}

